insert into public.tracks (id, title, area, area_label, subtitle, description, promise, teacher, status, launch_label, sort, price_label) values
  ('respira', 'Respira', 'mente', 'Mente', 'Ansiedade, pensar demais, sono e autoestima', 'Para quem sente que a cabeça não desliga. Práticas curtas para interromper a ruminação, dormir melhor e retomar o controle do dia.', 'Mente quieta, um dia por vez.', 'Edmilson', 'live', 'Disponível', 1, 'R$ 397 por ano'),
  ('ritmo', 'Ritmo', 'tempo', 'Gestão do tempo', 'Rotina, foco, prioridades e produtividade', 'Para quem termina o dia sem fazer o que importa. Um método simples de prioridades e uma rotina que cabe na vida real.', 'Uma rotina que cabe no seu dia.', 'Edmilson', 'soon', 'Fevereiro de 2027', 2, 'R$ 397 por ano'),
  ('eleva', 'Eleva', 'carreira', 'Carreira e negócios', 'Customer success, vendas, liderança e comunicação', 'Para quem quer crescer no trabalho com método: CS, vendas, retenção de clientes, liderança e posicionamento profissional.', 'Crescer no trabalho com método.', 'Especialistas convidados', 'soon', 'Fevereiro de 2027', 3, 'R$ 397 por ano'),
  ('prospera', 'Prospera', 'financas', 'Gestão financeira', 'Orçamento, dívidas, reserva e primeiros investimentos', 'Para quem ganha, mas não vê sobrar. Educação financeira prática para organizar o mês, sair das dívidas e montar a reserva.', 'O mês fecha no azul.', 'Especialista em finanças', 'soon', 'Abril de 2027', 4, 'R$ 397 por ano'),
  ('move', 'Move', 'corpo', 'Corpo', 'Movimento, treino em casa, energia e postura', 'Para quem está parado e sem tempo para academia. Treinos curtos em casa, em três níveis, com educador físico (CREF).', 'Um corpo que se mexe todo dia.', 'Educador físico (CREF)', 'soon', 'Abril de 2027', 5, 'R$ 397 por ano'),
  ('nutre', 'Nutre', 'alimentacao', 'Alimentação', 'Reeducação alimentar, rotina de refeições e compras', 'Para quem come mal na correria. Hábitos, cardápio da semana e lista de compras, com nutricionista (CRN), sem dieta da moda.', 'Comer bem sem complicar.', 'Nutricionista (CRN)', 'soon', 'Junho de 2027', 6, 'R$ 397 por ano')
